import { browser } from "wxt/browser";

/** Message keys generated by WXT from `public/_locales/en/messages.json`. */
export type I18nKey = Parameters<typeof browser.i18n.getMessage>[0];

/**
 * Thin wrapper over `browser.i18n` so popup/options code never calls the raw
 * API. Strings live in `public/_locales/<locale>/messages.json`.
 */
export function t(name: I18nKey, substitutions?: string | string[]): string {
	return browser.i18n.getMessage(name, substitutions) || name;
}

/**
 * The locale whose strings are actually being displayed — the `_locales`
 * directory Chrome resolved for this extension. `getUILanguage()` can report a
 * different UI language than the resolved message locale, so direction/lang
 * are driven by the sentinel keys each locale ships (`appLocale`,
 * `textDirection`).
 */
export function getResolvedLocale(): string {
	return browser.i18n.getMessage("appLocale") || browser.i18n.getUILanguage();
}

const RTL_LANGS = new Set(["ar", "fa", "he", "ur"]);

export function isRtl(locale: string = getResolvedLocale()): boolean {
	const base = locale.split("-")[0]?.toLowerCase() ?? "";
	return RTL_LANGS.has(base);
}

/** Set `lang`/`dir` on `<html>`; call before mounting the Svelte app. */
export function applyDocumentDirection(doc: Document = document): void {
	doc.documentElement.lang = getResolvedLocale();
	doc.documentElement.dir =
		browser.i18n.getMessage("textDirection") === "rtl" || isRtl() ? "rtl" : "ltr";
}
